u='https://aleselegis.al.se.leg.br/spl/consulta-producao.aspx?ano=2026';s=requests.Session();r=s.get(u,timeout=60); soup=BeautifulSoup(r.content,'html.parser'); form=soup.find('form'); data={x.get('name'):x.get('value','') for x in form.find_all('input') if x.get('name') and x.get('type') in (None,'hidden','text')}; data['__EVENTTARGET']='ctl00$ContentPlaceHolder1$ddl_ItensExibidos';data['__EVENTARGUMENT']='';data['ctl00$ContentPlaceHolder1$ddl_ItensExibidos']='100';p=s.post(u,data=data,timeout=120); print(p.status_code,len(p.content),p.headers.get('content-type')); open('artifacts/p20_7a_se_page100.html','wb').write(p.content); sp=BeautifulSoup(p.content,'html.parser');text=sp.get_text(' ',strip=True);print('5487',text.find('5487'),'rows links',len(sp.select('a[href*="processo.aspx?id="]')),'page links',[(a.get_text(strip=True),a.get('href')) for a in sp.select('a') if a.get_text(strip=True) in ['1','2','10']][-5:]); print('select',[(o.get('value'),o.has_attr('selected')) for o in sp.select('select option')])
